package dev.bennett.codexmeter;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import androidx.appcompat.app.*;
public final class BetaCatalogActivity extends AppCompatActivity {
    LinearLayout body;JSONObject state;boolean dark,titles;int filter,category=-1;String account;long generation;AlertDialog dialog;boolean registered;
    final BroadcastReceiver changed=new BroadcastReceiver(){public void onReceive(Context c,Intent i){load();}};
    @Override protected void onCreate(Bundle saved){Ui.applySelectedTheme(this);super.onCreate(saved);dark=Ui.isDark(this);titles=getIntent().getBooleanExtra("titles",false);if(saved!=null){filter=saved.getInt("filter");category=saved.getInt("category",-1);}body=Ui.installPage(this,BetaCopy.t(this,titles?"titles":"honors"),true).content;androidx.swiperefreshlayout.widget.SwipeRefreshLayout refresh=findViewById(R.id.dashboard_refresh);refresh.setEnabled(false);refresh.setRefreshing(false);}
    @Override protected void onResume(){super.onResume();if(!registered){androidx.core.content.ContextCompat.registerReceiver(this,changed,new IntentFilter(AppConstants.ACTION_USAGE_UPDATED),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);registered=true;}load();}
    @Override protected void onPause(){if(registered){unregisterReceiver(changed);registered=false;}super.onPause();}
    @Override protected void onDestroy(){generation++;if(dialog!=null)dialog.dismiss();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("filter",filter);out.putInt("category",category);}
    void load(){String key=SubscriptionStore.accountKey(this);long ticket=++generation;if(!java.util.Objects.equals(key,account)){account=key;state=null;if(dialog!=null)dialog.dismiss();body.removeAllViews();}body.removeAllViews();body.addView(BetaUi.note(this,getString(R.string.next_loading),dark));
        BetaGrowthStore.WORKER.execute(()->{JSONObject loaded=null;try{loaded=BetaGrowthStore.load(this,key);}catch(Exception ignored){}final JSONObject value=loaded;runOnUiThread(()->{if(ticket!=generation||!BetaUi.current(this,key))return;state=value;render();});});}
    void render(){body.removeAllViews();if(state==null){body.addView(BetaUi.note(this,BetaCopy.t(this,"pending_growth"),dark));return;}
        if(titles){LinearLayout preview=BetaUi.group(body,BetaCopy.t(this,"preview"),dark);preview.addView(BetaUi.title(this,BetaIdentity.title(this,state.optString("equipped")),dark));preview.addView(BetaUi.note(this,BetaCopy.t(this,"name_note"),dark));}
        String[] filters={"all","owned","progress"};LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(getResources().getConfiguration().fontScale>1.3f?LinearLayout.VERTICAL:LinearLayout.HORIZONTAL);for(int i=0;i<3;i++){final int index=i;Button button=BetaUi.action(this,BetaCopy.t(this,filters[i]),filter==i,dark,()->{filter=index;render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(getResources().getConfiguration().fontScale>1.3f?-1:0,-2,getResources().getConfiguration().fontScale>1.3f?0:1);button.setPadding(Ui.dp(this,6),Ui.dp(this,10),Ui.dp(this,6),Ui.dp(this,10));lp.topMargin=Ui.dp(this,8);if(i>0&&!(getResources().getConfiguration().fontScale>1.3f))lp.setMarginStart(Ui.dp(this,6));tabs.addView(button,lp);}body.addView(tabs);Ui.addSpacer(body,12);
        if(!titles){String[] categories={"all","start","routine","period","long"};Spinner chooser=new Spinner(this);String[] labels=new String[5];for(int i=0;i<labels.length;i++)labels[i]=BetaCopy.t(this,categories[i]);android.widget.ArrayAdapter<String> adapter=new android.widget.ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);chooser.setAdapter(adapter);chooser.setSelection(category+1);chooser.setMinimumHeight(Ui.dp(this,48));chooser.setContentDescription(BetaCopy.t(this,"honors"));chooser.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(category!=position-1){category=position-1;render();}}public void onNothingSelected(AdapterView<?> p){}});body.addView(chooser);}
        JSONObject facts=state.optJSONObject(titles?"titles":"honors");LinearLayout row=null;int shown=0;boolean stack=getResources().getConfiguration().fontScale>1.3f;
        for(String[] e:BetaCatalog.ALL){if(BetaCatalog.title(e[0])!=titles)continue;boolean owned=facts!=null&&facts.has(e[0]);if(filter==1&&!owned||filter==2&&owned||!titles&&category>=0&&Integer.parseInt(e[5])!=category)continue;
            if(stack||shown%2==0){row=new LinearLayout(this);row.setOrientation(stack?LinearLayout.VERTICAL:LinearLayout.HORIZONTAL);body.addView(row);Ui.addSpacer(body,12);}LinearLayout card=BetaUi.card(this,dark);card.setPadding(Ui.dp(this,12),Ui.dp(this,12),Ui.dp(this,12),Ui.dp(this,12));ImageView emblem=new ImageView(this);emblem.setImageDrawable(new BetaEmblem(e[0],owned,dark));emblem.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);card.addView(emblem,new LinearLayout.LayoutParams(Ui.dp(this,56),Ui.dp(this,56)));
            String label=BetaCatalog.name(e[0],BetaIdentity.name(this),BetaCopy.ko(this));card.addView(BetaUi.body(this,label,dark));int[] p=BetaCatalog.progress(state,e[0]);card.addView(BetaUi.note(this,Math.min(p[0],p[1])+" / "+p[1]+" · "+BetaCopy.t(this,owned?state.optString("equipped").equals(e[0])?"equipped":"earned":"locked"),dark));card.setContentDescription(label+", "+e[BetaCopy.ko(this)?3:4]+", "+BetaCopy.t(this,owned?"earned":"locked"));card.setTag("beta995:collectible:"+e[0]);card.setFocusable(true);card.setClickable(true);card.setOnClickListener(v->show(e[0]));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(stack?-1:0,-2,stack?0:1);if(!stack&&shown%2==1)lp.setMarginStart(Ui.dp(this,12));row.addView(card,lp);shown++;
        }if(shown==0)body.addView(BetaUi.note(this,BetaCopy.t(this,"no_items"),dark));if(!stack&&shown%2==1&&row!=null)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
    }
    void show(String id){if(!BetaUi.current(this,account))return;String[] e=BetaCatalog.find(id);if(e==null)return;JSONObject facts=state.optJSONObject(BetaCatalog.title(id)?"titles":"honors");boolean owned=facts.has(id);int[] p=BetaCatalog.progress(state,id);String text=e[BetaCopy.ko(this)?3:4]+"\n"+Math.min(p[0],p[1])+" / "+p[1]+"\n"+BetaCopy.t(this,"decorative")+(owned?"\n"+BetaCopy.t(this,"earned_at",BetaGrowthUi.time(this,facts.optLong(id))):"");
        if(dialog!=null)dialog.dismiss();AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(BetaCatalog.name(id,BetaIdentity.name(this),BetaCopy.ko(this))).setMessage(text).setNegativeButton(BetaCopy.t(this,"close"),null);
        if(owned&&BetaCatalog.title(id)){boolean equipped=id.equals(state.optString("equipped"));builder.setPositiveButton(BetaCopy.t(this,equipped?"unequip":"equip"),(d,w)->BetaUi.task(this,account,()->BetaGrowthStore.equip(this,account,equipped?"":id),this::load));}dialog=builder.create();dialog.show();
    }
}
